<?php declare(strict_types=1); require dirname(__DIR__).'/includes/bootstrap.php'; require ROOT_PATH.'/includes/members.php';$success=false;$id=(int)($_GET['id']??0);$token=(string)($_GET['token']??'');if($id&&preg_match('/^[a-f0-9]{64}$/',$token)&&($db=database())){$s=$db->prepare('UPDATE wts_members SET email_confirmed_at=COALESCE(email_confirmed_at,NOW()),confirmation_token_hash=NULL WHERE id=? AND confirmation_token_hash=?');$s->execute([$id,hash('sha256',$token)]);$success=$s->rowCount()>0;}$pageTitle='Confirm account | Word Truth Spirit';require ROOT_PATH.'/includes/header.php';?><main class="member-auth-page"><section class="member-auth-card"><p class="kicker">Reader account</p><h1><?=$success?'Your email is confirmed.':'This confirmation link is no longer valid.'?></h1><p><?=$success?'Your account is ready. Sign in to create your profile and see your checkout activity.':'Confirmation links can only be used once. If you still need help, please contact us.'?></p><a class="button button-primary" href="<?=url($success?'members/login.php':'contact.php')?>"><?=$success?'Sign in':'Contact us'?></a></section></main><?php require ROOT_PATH.'/includes/footer.php'; ?>
